/**
 * thinking 레벨 지원 여부 — pi 카탈로그(`models-store.json` 형태)와 pi의
 * `models.json` `modelOverrides`를 합쳐 본다. 업체 이름으로 갈래를 두지 않는다.
 *
 * pi의 `thinkingLevelMap`은 레벨 → 업체 쪽 이름이며, `null`이면 그 레벨을
 * 지원하지 않는다. 키가 없으면 레벨 이름 그대로 보내는 것으로 본다.
 */
import type { Effort } from "./config.ts";

type Json = Record<string, unknown>;

const record = (value: unknown): Json | null => (value && typeof value === "object" && !Array.isArray(value) ? (value as Json) : null);

function overrideMap(overrides: unknown, provider: string, modelId: string): Json {
	const root = record(overrides);
	const providers = record(root?.providers);
	const byProvider = record(providers?.[provider]);
	const modelOverrides = record(byProvider?.modelOverrides);
	const model = record(modelOverrides?.[modelId]);
	return record(model?.thinkingLevelMap) ?? {};
}

/** `off` 레벨을 업체가 받는가. 없으면 false. */
export function offAllowed(store: unknown, overrides: unknown, provider: string, modelId: string): boolean {
	const providerEntry = record(record(store)?.[provider]);
	const models = providerEntry?.models;
	if (!Array.isArray(models)) return false;
	const model = models.find((entry) => record(entry)?.id === modelId);
	const modelRecord = record(model);
	if (!modelRecord) return false;
	const merged: Json = { ...(record(modelRecord.thinkingLevelMap) ?? {}), ...overrideMap(overrides, provider, modelId) };
	if (!("off" in merged)) return true;
	const off = merged.off;
	return off !== null && off !== undefined && off !== false && off !== "";
}

/** `off`를 못 받는 업체에는 lowest 레벨로 보낸다. */
export function sendEffort(effort: Effort | undefined, offIsAllowed: boolean): Effort | undefined {
	if (effort === "off" && !offIsAllowed) return "low";
	return effort;
}

