/** 공통 층(system 뒤에 붙일 문구)을 한 번만 끝에 붙인다. 이미 있으면 그대로(같은 참조). */
export function withCommon(system: unknown, common: string): unknown {
	if (!common) return system;
	if (typeof system === "string") {
		if (!system) return common;
		if (system === common || system.endsWith(`\n\n${common}`)) return system;
		return `${system}\n\n${common}`;
	}
	if (Array.isArray(system)) {
		if (system.some((block) => recordOf(block)?.type === "text" && recordOf(block)?.text === common)) return system;
		return [...system, { type: "text", text: common }];
	}
	if (system === undefined || system === null) return [{ type: "text", text: common }];
	return system;
}

